//! Checks the covariance and mean estimators against NumPy and pandas implementations written
//! from their published sources: the authors' code for shrinkage towards constant correlation
//! and for analytical nonlinear shrinkage, principal components and the Marchenko–Pastur edge
//! from `numpy.linalg.eigh`, the Efron–Morris intensity of the James–Stein mean, and pandas'
//! exponentially weighted mean. The fixture is generated by `scripts/reference/estimators.py`.

#![allow(clippy::unwrap_used)]

use finalytics_risk::*;
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/estimators.json")).unwrap()
}

fn floats(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect()
}

#[track_caller]
fn all_close(actual: &[f64], expected: &[f64], tolerance: f64, what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}");
    let scale = expected.iter().fold(0.0f64, |m, x| m.max(x.abs()));
    for (k, (a, e)) in actual.iter().zip(expected).enumerate() {
        assert!(
            (a - e).abs() <= tolerance * scale,
            "{what}[{k}]: {a} against the reference {e}"
        );
    }
}

fn table(case: &Value) -> ReturnsTable {
    let labels = case["labels"]
        .as_array()
        .unwrap()
        .iter()
        .map(|l| l.as_str().unwrap().to_owned())
        .collect();
    let columns = case["columns"]
        .as_array()
        .unwrap()
        .iter()
        .map(floats)
        .collect();
    ReturnsTable::new(labels, columns).unwrap()
}

#[test]
fn covariance_estimators_match_the_reference() {
    for case in fixture()["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let returns = table(case);
        let constant = covariance(&returns, CovarianceMethod::ConstantCorrelation).unwrap();
        all_close(
            constant.matrix.values(),
            &floats(&case["constant_correlation"]["matrix"]),
            1e-12,
            &format!("{name}: constant correlation"),
        );
        let shrinkage = case["constant_correlation"]["shrinkage"].as_f64().unwrap();
        assert!(
            (constant.shrinkage.unwrap() - shrinkage).abs() < 1e-12,
            "{name}"
        );
        let factors = case["statistical"]["factors"].as_u64().unwrap() as usize;
        all_close(
            covariance(&returns, CovarianceMethod::Statistical { factors })
                .unwrap()
                .matrix
                .values(),
            &floats(&case["statistical"]["matrix"]),
            1e-10,
            &format!("{name}: statistical"),
        );
        all_close(
            covariance(&returns, CovarianceMethod::Denoised)
                .unwrap()
                .matrix
                .values(),
            &floats(&case["denoised"]),
            1e-10,
            &format!("{name}: denoised"),
        );
        // With more assets than returns the estimator is ill-conditioned: changing the returns
        // by one part in 1e14 moves the reference by about 3e-7 of its largest entry, so the
        // two implementations' rounding differs by about 3e-8.
        let tolerance = if returns.assets() < returns.observations() {
            1e-10
        } else {
            1e-7
        };
        all_close(
            covariance(&returns, CovarianceMethod::NonlinearShrinkage)
                .unwrap()
                .matrix
                .values(),
            &floats(&case["nonlinear_shrinkage"]),
            tolerance,
            &format!("{name}: nonlinear shrinkage"),
        );
    }
}

#[test]
fn mean_estimators_match_the_reference() {
    for case in fixture()["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let returns = table(case);
        let decay = case["ewma_mean"]["decay"].as_f64().unwrap();
        all_close(
            &mean_returns(&returns, MeanMethod::Ewma { decay })
                .unwrap()
                .means,
            &floats(&case["ewma_mean"]["means"]),
            1e-13,
            &format!("{name}: exponentially weighted mean"),
        );
        let found = mean_returns(&returns, MeanMethod::JamesStein);
        match case["james_stein"].as_object() {
            Some(js) => {
                let found = found.unwrap();
                all_close(
                    &found.means,
                    &floats(&js["means"]),
                    1e-12,
                    &format!("{name}: James–Stein"),
                );
                let intensity = js["intensity"].as_f64().unwrap();
                assert!((found.shrinkage.unwrap() - intensity).abs() < 1e-12);
            }
            // More assets than returns: the sample covariance has no inverse.
            None => assert!(found.is_err(), "{name}"),
        }
    }
}

#[test]
fn estimators_read_by_name() {
    let read = |text: &str| serde_json::from_str::<CovarianceMethod>(text);
    assert_eq!(
        read(r#""nonlinear_shrinkage""#).unwrap(),
        CovarianceMethod::NonlinearShrinkage
    );
    assert_eq!(
        read(r#"{"type": "statistical", "factors": 3}"#).unwrap(),
        CovarianceMethod::Statistical { factors: 3 }
    );
    let bare = read(r#""statistical""#).unwrap_err().to_string();
    assert!(bare.contains("needs its number of factors"), "{bare}");
    let mean = |text: &str| serde_json::from_str::<MeanMethod>(text);
    assert_eq!(mean(r#""james_stein""#).unwrap(), MeanMethod::JamesStein);
    assert_eq!(
        mean(r#"{"type": "ewma"}"#).unwrap(),
        MeanMethod::Ewma { decay: 0.94 }
    );
    assert!(mean(r#""shrunk""#).is_err());
}
